/**
 *
 * ListboxList is a component that renders the list of options within the Listbox component.
 *
 * [Live Demo](https://www.primereact.org/listbox/)
 *
 * @module ListboxList
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { ListboxRootInstance } from './ListboxRoot.types';
/**
 * Defines passthrough(pt) options type in ListboxList component.
 */
export type ListboxListPassThroughType<E> = PassThroughType<ListboxListInstance, E>;
/**
 * Defines passthrough(pt) options of ListboxList component.
 */
export interface ListboxListPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: ListboxListPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in ListboxList component.
 * @template T The type of the option data.
 */
export interface ListboxListProps<T = unknown> extends BaseComponentProps<ListboxListInstance<T>, unknown, ListboxListPassThrough> {
}
/**
 * Defines valid state in ListboxList component.
 */
export interface ListboxListState {
}
/**
 * Defines the methods and properties exposed by ListboxList component.
 * @template T The type of the option data.
 */
export interface ListboxListExposes<T = unknown> {
    /**
     * The ListboxList component instance.
     */
    listbox: ListboxRootInstance<T> | undefined | null;
    /**
     * The options available in the Listbox.
     */
    options: T[] | undefined | null;
}
/**
 * Instance of ListboxList component.
 * @template T The type of the option data.
 */
export type ListboxListInstance<T = unknown> = ComponentInstance<ListboxListProps<T>, ListboxListState, ListboxListExposes<T>>;
